<?php
namespace App\Services;
use App\Domain\Workflow\{StepExecutionStatus,WorkflowExecutionStatus};use App\Jobs\ExecuteWorkflowStep;use App\Models\{StepExecution,Workflow,WorkflowExecution};use DomainException;use Illuminate\Support\Facades\{Cache,DB};use Illuminate\Database\UniqueConstraintViolationException;
final class TriggerWorkflow
{
 public function __construct(private ExecutionAdmission $admission,private WorkflowQueue $queues){}
 public function trigger(Workflow $workflow,string $triggerType,string $idempotencyKey,array $context=[]):WorkflowExecution{$version=$workflow->currentVersion()->with('steps')->firstOrFail();if($existing=WorkflowExecution::where(['organization_id'=>$workflow->organization_id,'workflow_version_id'=>$version->id,'idempotency_key'=>$idempotencyKey])->first())return $existing;$lock=Cache::lock("qf:admission:{$workflow->organization_id}",10);if(!$lock->get())throw new DomainException('execution_admission_busy');try{$execution=DB::transaction(function()use($workflow,$version,$triggerType,$idempotencyKey,$context){if($existing=WorkflowExecution::where(['organization_id'=>$workflow->organization_id,'workflow_version_id'=>$version->id,'idempotency_key'=>$idempotencyKey])->first())return $existing;$this->admission->assertAndIncrement($workflow);$context=['__organization_id'=>$workflow->organization_id,'__workflow_id'=>$workflow->id,...$context];$e=WorkflowExecution::create(['organization_id'=>$workflow->organization_id,'workflow_version_id'=>$version->id,'trigger_type'=>$triggerType,'idempotency_key'=>$idempotencyKey,'status'=>WorkflowExecutionStatus::Pending,'context_json'=>$context]);foreach($version->steps as $step)StepExecution::create(['workflow_execution_id'=>$e->id,'workflow_step_id'=>$step->id,'logical_key'=>"{$e->id}:{$step->key}",'status'=>StepExecutionStatus::Pending,'attempt_count'=>0]);return $e;},3);}catch(UniqueConstraintViolationException){$execution=WorkflowExecution::where(['organization_id'=>$workflow->organization_id,'workflow_version_id'=>$version->id,'idempotency_key'=>$idempotencyKey])->firstOrFail();}finally{$lock->release();}ExecuteWorkflowStep::dispatch($execution->id)->onQueue($this->queues->name($workflow));return $execution;}
}
